using System.Collections.ObjectModel;

namespace FRP1.Plugin;

internal enum HelpTopicId
{
    FirstSteps, Rules, Age, ProfileSelect, NewProfile, SaveProfile, Discard, PublicSharing,
    CharacterFields, Mature, Status, Availability, Glances, Hooks, Reorder, ExtraFields,
    Import, Export, Clipboard, ThemeAuto, ThemeManual, Decorations,
    BarVisible, BarLock, BarScale, BarReset, BarOpen, Unavailable,
    Network, Trust, IpConsent, Sharing, Block, Binding, Notes, Reader, Portrait, Formatting,
    Companions, Environment, Contacts, Preferences,
    LocalTools, Automation, ProfileLinks, Language, GamePresentation, Map,
    OocInformation, FurtherCharacterData, RpExperience, BarCollapse, TargetContext, ExistingAdditionalContent,
}

internal sealed record HelpTopic(string Title, string Summary, string Details);

internal static class HelpContent
{
    public static IReadOnlyDictionary<HelpTopicId, HelpTopic> All { get; } = new ReadOnlyDictionary<HelpTopicId, HelpTopic>(
        new Dictionary<HelpTopicId, HelpTopic>
        {
            [HelpTopicId.FirstSteps] = new("Erste Schritte", "Hinweise bestätigen, Altersauswahl treffen und unter Mein Charakter dein Profil anlegen.", "Bearbeiten öffnet deinen Entwurf in den Bereichen Überblick, Charakter und OOC. Über + Angabe ergänzt du freiwillige Felder. Speichern übernimmt den Entwurf lokal; Vorschau zeigt ihn lesend. Profilvarianten und JSON findest du im Menü. Aktiviere ein gespeichertes Profil ausdrücklich in deiner RP-Leiste. Kontakte enthält auch die Umgebung; Einstellungen zeigt jeweils eine gewählte Kategorie. Netzwerk aktivieren, koppeln und teilen bleiben getrennte bewusste Entscheidungen."),
            [HelpTopicId.Rules] = new("Profilregeln", "Allgemeine Profile müssen jugendfrei bleiben.", "Lies die Profilregeln und bestätige sie bewusst. Diese lokale Bestätigung ist von der Altersauswahl getrennt. Die vollständigen Regeln bleiben in den Einstellungen erreichbar."),
            [HelpTopicId.Age] = new("Dein tatsächliches Alter", "Die Altersauswahl betrifft dich, nicht deinen RP-Charakter.", "Wähle pro Pluginsitzung wahrheitsgemäß unter 18 oder 18 und älter. Nur Erwachsene können Inhalte ab 18 zusätzlich freigeben. Dies ist eine Selbstauskunft, keine automatische Altersprüfung. Ein Wechsel verwirft offene Entwürfe und gesperrte Ansichten."),
            [HelpTopicId.ProfileSelect] = new("Profilwahl", "Editorprofil und aktives Leistenprofil sind getrennte Auswahlen.", "Die Profilwahl im Editor öffnet einen Entwurf. Die Auswahl des aktiven RP-Profils ordnet ein gespeichertes Profil deinem derzeitigen Spielcharakter zu. Speichere oder verwirf offene Änderungen vor einem Wechsel."),
            [HelpTopicId.NewProfile] = new("Neues Profil", "Erstellt einen neuen lokalen Entwurf.", "Fülle mindestens den RP-Namen aus und speichere den Entwurf. Mehrere Profile können unabhängig voneinander bestehen. Ein neues Profil wird nicht automatisch aktiv oder geteilt."),
            [HelpTopicId.SaveProfile] = new("Lokal speichern", "Speichert den Entwurf auf diesem Gerät.", "Speichern erhöht die Profilversion und übernimmt die Änderungen in den lokalen Katalog. Es ist keine Veröffentlichung oder Netzwerkfreigabe. Während des Speicherns sind konkurrierende Leistenänderungen gesperrt."),
            [HelpTopicId.Discard] = new("Änderungen verwerfen", "Stellt den zuletzt gespeicherten Stand des Entwurfs wieder her.", "Ungespeicherte Eingaben gehen dabei verloren. Gespeicherte Profile werden nicht gelöscht. Danach sind Statusänderungen und die aktive Profilwahl in der RP-Leiste wieder möglich."),
            [HelpTopicId.PublicSharing] = new("Speichern, Exportieren und Teilen", "Die drei Profilbereiche ordnen die Bearbeitung; sie erteilen keine Veröffentlichungserlaubnis.", "Speichern bleibt lokal. Für Direktaustausch musst du Netzwerk, Kopplung, das zu teilende Profil und die Freigabe je Gegenstelle bewusst wählen. Bestehende Zusatzinhalte aus älteren Profilen werden durch die vereinfachte Ansicht weder gelöscht noch privat. Prüfe diese Inhalte im Bereich Vorhandene Zusatzinhalte, bevor du exportierst oder ein vollständiges Profil teilst. Journal und RP-Leiste erteilen keine neue Freigabe."),
            [HelpTopicId.CharacterFields] = new("Charakterdaten", "Diese Felder beschreiben deinen RP-Charakter.", "RP-Name, Titel, Herkunft und weitere Angaben sind frei gestaltbare Profilinhalte. Das Charakteralter in diesen Feldern ersetzt niemals deine tatsächliche Altersauswahl. Die Vorschau zeigt den aktuellen Entwurf."),
            [HelpTopicId.Mature] = new("Profil ab 18", "Die Kennzeichnung gilt für das gesamte Profil.", "Nicht jugendfreie Inhalte müssen als ab 18 gekennzeichnet sein. Allgemeine Profile dürfen solche Inhalte auch in Namen, Titeln, Glances oder Zusatzfeldern nicht enthalten. Die Kennzeichnung ist keine automatische Inhaltsprüfung."),
            [HelpTopicId.Status] = new("IC, OOC und AFK", "IC: in der Rolle. OOC: außerhalb der Rolle. AFK: abwesend.", "Der RP-Status beschreibt, wie du gerade spielst. In der Leiste ändert er das aktive gespeicherte Profil. Er ist unabhängig davon, ob du gerade neue RP-Begegnungen suchst."),
            [HelpTopicId.Availability] = new("RP-Verfügbarkeit", "Offen, beschäftigt oder kein RP beschreibt deine Bereitschaft für Begegnungen.", "Die Verfügbarkeit ist vom IC/OOC/AFK-Status getrennt. Du kannst beispielsweise IC sein und trotzdem kein neues RP suchen. Die Leiste speichert diese Auswahl im aktiven Profil."),
            [HelpTopicId.Glances] = new("Auf den ersten Blick", "Ein Icon steht für einen kurzen wahrnehmbaren Eindruck deines Charakters.", "Wähle oder bearbeite den Eintrag im Profil und aktiviere nur die gewünschten Eindrücke. Die verfügbaren Spielicons kommen aus lokalen Spieldaten. Ein Glance-Text ist Profilinhalt: Er bleibt auch bei ausgeschalteten Bedienhilfen erreichbar. Deaktivierte Einträge bleiben gespeichert. Die gemeinsame Alterskennzeichnung gilt auch für diese Inhalte."),
            [HelpTopicId.Hooks] = new("Vorhandene RP-Anknüpfungspunkte", "Ältere Profile können bereits Ideen für Begegnungen enthalten.", "Die vereinfachte Neuanlage legt dafür keinen zusätzlichen Bearbeitungsbereich an. Bereits gespeicherte Anknüpfungspunkte bleiben Profilinhalt und sind unter Vorhandene Zusatzinhalte prüfbar. Entfernen oder ändern der Ansicht macht solche Daten nicht privat; kontrolliere sie vor Export und Freigabe."),
            [HelpTopicId.Reorder] = new("Einträge ordnen", "Nach oben und nach unten ändern die Reihenfolge.", "Die Änderung bleibt zunächst im Entwurf. Entfernen löscht diesen Eintrag aus dem Entwurf; erst Speichern übernimmt die neue Liste. Verwerfen holt den gespeicherten Stand zurück."),
            [HelpTopicId.ExtraFields] = new("Vorhandene Zusatzfelder", "Ältere Profile können zusätzliche frei benannte Angaben enthalten.", "Die vereinfachte Neuanlage bietet dafür keinen eigenen neuen Bearbeitungsbereich. Gespeicherte Zusatzfelder bleiben jedoch öffentliche Profilinhalte. Prüfe sie unter Vorhandene Zusatzinhalte vor Export und Teilen; ein ausgeblendetes Bearbeitungsfeld ist keine private Notiz."),
            [HelpTopicId.Import] = new("JSON importieren", "Ein Import erzeugt eine neue lokale Profilkopie.", "Füge ein gültiges FRP1-Profil ein. Bestehende Profile werden nicht überschrieben. Ungültige, zu große oder für deine Altersauswahl gesperrte Profile werden abgelehnt. Speichere anschließend die neue Kopie."),
            [HelpTopicId.Export] = new("JSON exportieren", "Ein Export enthält das öffentliche Profil einschließlich erhaltener älterer Zusatzinhalte.", "Exportieren speichert den Entwurf nicht und baut keine Verbindung auf. Prüfe auch vorhandene Anknüpfungspunkte, Merkmale, Begleiter und Zusatzfelder, bevor du die Datei weitergibst. Eine vereinfachte Bearbeitungsansicht entfernt diese Inhalte nicht automatisch. Private Notizen, lokale Zuordnungen und Altersangaben gehören nicht zum öffentlichen Export."),
            [HelpTopicId.Clipboard] = new("JSON kopieren", "Kopiert den angezeigten JSON-Text in die Zwischenablage.", "Andere Programme können anschließend auf den kopierten Text zugreifen. Kopieren veröffentlicht nichts automatisch und verändert keine Profile."),
            [HelpTopicId.ThemeAuto] = new("Automatische Darstellung", "Die bisherige automatische Auswahl bleibt lesbar und verwendet die Obsidian-Palette.", "Gespeicherte Volkstheme-IDs bleiben gültig. Für eine abweichende Darstellung wählst du Pergament oder Nachtblau ausdrücklich aus. Bis die Einstellungen geladen sind und ohne angemeldeten Charakter bleibt Obsidian aktiv."),
            [HelpTopicId.ThemeManual] = new("Darstellung frei wählen", "Obsidian, Pergament und Nachtblau stehen unabhängig vom Volk zur Verfügung.", "Die Auswahl wird lokal für den Spielcharakter gespeichert. Bestehende Theme-IDs bleiben unter Bisherige Auswahl erreichbar; alte automatische Volksthemes verwenden jetzt die ruhige Obsidian-Palette. Profilinhalte und Altersfreigaben bleiben unverändert."),
            [HelpTopicId.Decorations] = new("Verzierungen reduzieren", "Blendet die dezente Akzentlinie aus.", "Farben und Bedienung bleiben erhalten. Diese Einstellung verändert nur die Darstellung deiner FRP1-Fenster und keine anderen Plugins."),
            [HelpTopicId.BarVisible] = new("RP-Leiste anzeigen", "Blendet das kompakte RP-Bedienfeld ein oder aus.", "Die Leiste ist erst nach Hinweisbestätigung und Altersauswahl mit angemeldetem Charakter verfügbar. Sie steuert ausschließlich dein ausdrücklich aktiviertes eigenes Profil. Fremde Profile bleiben in Zielkarte, Mouseover und Journal erreichbar. /frp bar show zeigt die Leiste wieder, ohne eine fehlende Zugriffsfreigabe zu ersetzen."),
            [HelpTopicId.BarLock] = new("Position sperren", "Verhindert versehentliches Verschieben.", "Statusschalter, Profilwahl und Einblicke bleiben bedienbar. Entferne die Sperre, um die Leiste an ihrer Titelleiste zu verschieben."),
            [HelpTopicId.BarScale] = new("Leistengröße", "Vergrößert nur die RP-Leiste.", "Schrift und Abstände werden lokal für dieses Fenster angepasst. Das Hauptfenster und andere Plugins bleiben unverändert. Die Leiste wird innerhalb des sichtbaren Spielbereichs gehalten."),
            [HelpTopicId.BarReset] = new("Position zurücksetzen", "Holt die Leiste an eine sichtbare Ausgangsposition zurück.", "Das ist auch bei ausgeblendeter oder außerhalb liegender Leiste über die Einstellungen möglich. Profile, aktive Zuordnung, Altersauswahl und Netzwerkfreigaben bleiben unverändert."),
            [HelpTopicId.BarOpen] = new("Eigenes Profil öffnen", "Öffnet Mein Charakter mit deinem aktiven eigenen Profil.", "Die Charakterkarte zeigt den gespeicherten Stand. Ein offener Entwurf bleibt erhalten und wird durch die Leiste nicht ersetzt. Die Leiste verändert ausschließlich das ausdrücklich aktivierte eigene Profil."),
            [HelpTopicId.Unavailable] = new("Technische Grenzen", "Unbekannte Gegenstellen werden nicht automatisch im Internet gesucht.", "Direktverbindungen können an Routern oder Firewalls scheitern. Die Verbindung und die Spielanzeigen sind noch nicht in allen realen Netzwerken oder im laufenden Spiel abgenommen."),
            [HelpTopicId.Network] = new("Direktverbindungen", "Netzwerk bleibt nach jedem Start aus, bis du es ausdrücklich aktivierst.", "Es gibt keine Registrierung, Vermittlungsserver oder zentrale Profildatenbank. Wähle einen lokalen Netzwerkadapter und bestätige die direkte IP-Sichtbarkeit. Eine Einladung überwindet Router- oder Firewallgrenzen nicht."),
            [HelpTopicId.Trust] = new("Gegenstelle koppeln", "Vergleicht und bestätigt die öffentliche kryptografische Identität.", "Tauscht Einladungen über einen vertrauenswürdigen Weg aus. Die Kopplung prüft Schlüsselbesitz, nicht den Besitz eines FFXIV-Charakters. Koppeln veröffentlicht noch kein Profil."),
            [HelpTopicId.IpConsent] = new("Direkte IP-Sichtbarkeit", "Bei einer Direktverbindung sehen die beteiligten Gegenstellen eure IP-Adressen.", "Diese Zustimmung gilt für die Sitzung. Einladungen enthalten Verbindungsadresse und öffentlichen Fingerprint. Teile sie bewusst; eine IP-Freigabe wird weder aus Altersauswahl noch Journalöffnung abgeleitet."),
            [HelpTopicId.Sharing] = new("Profilfreigabe", "Wähle das aktive Profil zum Teilen aus und gib es je Gegenstelle frei.", "Lokal speichern und aktivieren veröffentlichen nichts. Profilveröffentlichung pausieren oder die Peerfreigabe zurücknehmen stoppt weitere Übertragung. Bereits empfangene Kopien anderer Geräte lassen sich dadurch nicht zurückholen."),
            [HelpTopicId.Block] = new("Lokal sperren", "Eine Sperre unterbindet Anzeige und weiteren Austausch mit dieser Gegenstelle.", "Sperren wirken lokal und werden nicht an einen Moderationsserver gemeldet. Aufheben ist eine eigene bewusste Entscheidung. Eine Stummschaltung der Anzeige ist von einer Netzwerksperre zu unterscheiden."),
            [HelpTopicId.Binding] = new("Charakterzuordnung bestätigen", "Ordnet ein bekanntes Profil bewusst einem Spielcharakter zu.", "Name und Heimatwelt allein beweisen keinen Schlüsselbesitz. Bestätige die Zuordnung erst, wenn du sie mit der Person abgeglichen hast. Mehrdeutige oder gesperrte Zuordnungen werden nicht als lesbares Zielprofil behandelt."),
            [HelpTopicId.Notes] = new("Private Notizen", "Notizen, Beziehungen und lokale Aliasnamen bleiben auf deinem Gerät.", "Diese Angaben gehören nicht zum öffentlichen Profil und werden nicht exportiert oder mit anderen Clients geteilt. Eine Favoritenmarkierung erteilt keine Profilfreigabe."),
            [HelpTopicId.Reader] = new("Profiljournal lesen", "Überblick, Charakter und OOC zeigen den erlaubten Profilinhalt.", "Die Charakterkarte zeigt den gespeicherten Stand; die ausdrücklich gewählte Vorschau liest deinen aktuellen Entwurf. Fremde Profile öffnen in einem eigenen Journal. Vorhandene ältere Zusatzinhalte bleiben erreichbar. Lesen erlaubt weder einen neuen Austausch noch die Freigabe eines gesperrten Profils."),
            [HelpTopicId.Portrait] = new("Portrait und Symbole", "Wähle lokale Bilder und einen sichtbaren quadratischen Ausschnitt.", "PNG und JPEG werden lokal normalisiert. Erst Vorschau und Übernehmen ändern den Entwurf; Speichern übernimmt ihn ins Profil. Verwende nur erlaubte Bilder. Profilwechsel oder entzogene Freigabe verwerfen veraltete Auswahlrückmeldungen."),
            [HelpTopicId.Formatting] = new("Öffentliche Profilgestaltung", "Layout, Farben und begrenzte Textmarkierungen gestalten das Profiljournal.", "Überschriften, Listen, fett, kursiv und Textfarben sind möglich. Unbekannte Markierungen bleiben Text; es werden keine Skripte oder entfernten Inhalte geladen. Das persönliche Fenstertheme ist eine getrennte lokale Einstellung."),
            [HelpTopicId.Companions] = new("Vorhandene Begleiterangaben", "Ältere Profile können bereits selbst beschriebene Begleiter enthalten.", "Die vereinfachte Neuanlage fügt keine neue Begleiterverwaltung hinzu. Gespeicherte Namen, Beschreibungen und Icons bleiben jedoch öffentliche Profilinhalte und erben dessen Alterskennzeichnung. Prüfe vorhandene Angaben unter Vorhandene Zusatzinhalte vor Export und Teilen. Daraus entsteht keine bestätigte Zuordnung zu einem Spielobjekt."),
            [HelpTopicId.Environment] = new("Umgebung und Zielprofile", "Zeigt lokale Spielerbeobachtungen und ausdrücklich zugeordnete erlaubte Profile.", "Unbekannte Spieler lösen keine Verbindungen aus. Lesbare Ziele und Mouseover-Inhaltstooltips verwenden dieselben Alters-, Sperr- und Zuordnungsregeln. Diese Inhaltstooltips bleiben von den abschaltbaren Bedienhilfen unabhängig."),
            [HelpTopicId.Contacts] = new("Kontakte und Verlauf", "Suche im erlaubten lokalen Cache und pflege Favoriten, Notizen und Zuordnungen.", "Offline-Kopien bleiben als solche erkennbar. Verlauf und Beziehungen sind privat. Kontakte zeigen nur Profile, die nach den aktuellen Freigaben und Sperren gelesen werden dürfen."),
            [HelpTopicId.Preferences] = new("Vorhandene RP-Absprachen", "Ältere Profile können über Erfahrung und Spielstil hinaus weitere Gesprächshinweise enthalten.", "Bereits gespeicherte Angaben zu Verletzungen, Charaktertod, Romantik oder anderen Szenen bleiben unter Vorhandene Zusatzinhalte prüfbar. Sie ersetzen keine Einwilligung oder konkrete Absprache und gehören zum öffentlichen Profil. Die vereinfachte Neuanlage ergänzt dafür keine weiteren Einstellungsblöcke; Altersauswahl und Netzwerkfreigaben bleiben getrennt."),
            [HelpTopicId.LocalTools] = new("Lokale RP-Werkzeuge", "Text- und NPC-Entwürfe bereiten Inhalte für deine Szene vor.", "Ein Entwurf steuert keine NPCs und sendet keine Spielnachrichten. Prüfe den Text und kopiere ihn bei Bedarf selbst. Profilverweise öffnen nur bereits lokal vorhandene und aktuell erlaubte Profile."),
            [HelpTopicId.Automation] = new("Lokale Automatisierung", "Bewusst aktivierte Regeln ändern nur dein eigenes gespeichertes Profil.", "Anmeldung, Kampf, Duty und Gebietswechsel können Status, Verfügbarkeit oder aktive Profilwahl auslösen. Offene Entwürfe, laufende Vorgänge und Freigaben bleiben wirksam. Vorübergehendes Ausblenden verändert weder gespeicherte Sichtbarkeit noch Netzwerk- oder Profilfreigaben."),
            [HelpTopicId.ProfileLinks] = new("Interne Profilverweise", "Ein Verweis enthält öffentliche Identität und Profil-ID; er verbindet niemanden automatisch.", "Nur vorhandene erlaubte Profile werden geöffnet. Ein eigener Verweis kann hier erst mit gespeicherten Profildaten und einer ausdrücklich aktiven Direktverbindung erstellt werden; dafür wird kein zusätzlicher Listener gestartet."),
            [HelpTopicId.Language] = new("Oberflächensprache", "Deutsch und Englisch betreffen die lokale Bedienoberfläche.", "Die Sprache wird lokal gespeichert. Profiltexte werden nicht übersetzt. Noch nicht übersetzte Hinweise behalten ihren vorhandenen Text; Sprachwahl erteilt keinerlei Alters- oder Netzwerkfreigabe."),
            [HelpTopicId.GamePresentation] = new("Lokale Spielanzeige", "RP-Namen, Titel, Farben und lokale Chatnamen sind standardmäßig ausgeschaltet.", "Nur bekannte, ausdrücklich zugeordnete und aktuell erlaubte Profile werden verwendet. Chatnachrichten werden nicht gesendet oder verändert; die lokale Namensanzeige behält das echte Klickziel. Bereits gedruckte Chatgeschichte kann bei einer späteren Sperre nicht zuverlässig rückwirkend bereinigt werden."),
            [HelpTopicId.Map] = new("Bekannte Charaktere auf der Karte", "Zeigt nur erlaubte Zuordnungen gerade lokal sichtbarer Spieler.", "Eine Kartenmarkierung öffnet sich nur durch deinen Klick. Positionen werden nicht übertragen; dies ist keine globale Spielerliste. Gebietsdaten und Zuordnungen müssen zur aktuellen Szene passen."),
            [HelpTopicId.OocInformation] = new("OOC-Informationen", "Hier stehen Informationen über deine RP-Absprachen außerhalb der Rolle.", "Beschreibe beispielsweise gewünschte Kontaktaufnahme oder organisatorische Hinweise. Dieser Text gehört zum öffentlichen Profil und kann mit ihm exportiert oder ausdrücklich geteilt werden. Veröffentliche keine fremden privaten Daten. Private Kontakt-Notizen werden separat und ausschließlich lokal gespeichert."),
            [HelpTopicId.FurtherCharacterData] = new("Weitere Charakterdaten", "Ergänze wahrnehmbare und biografische Angaben zu deinem RP-Charakter.", "Augenfarbe, Größe, Gewicht, Geburtsort, Wohnort und RP-Sprachen sind freiwillige Profilangaben. Sie beschreiben den Charakter; das frei eingetragene Charakteralter ersetzt niemals die Altersauswahl der realen Person. Speichern übernimmt die Angaben in das lokale Profil und erteilt keine neue Netzwerkfreigabe."),
            [HelpTopicId.RpExperience] = new("RP-Erfahrung und Spielstil", "Eine kurze Selbstauskunft hilft beim Einstieg in ein gemeinsames Spiel.", "Du kannst deine Erfahrung und den bevorzugten RP-Stil angeben. Diese Angaben sind Gesprächshinweise, keine Einwilligung zu bestimmten Szenen. Bestehende weitergehende Absprachen eines älteren Profils bleiben unter Vorhandene Zusatzinhalte sichtbar und werden nicht durch die neue Navigation gelöscht."),
            [HelpTopicId.BarCollapse] = new("RP-Leiste ein- und ausklappen", "Zusammenklappen reduziert das Bedienfeld; deine Profile bleiben unverändert.", "Der Klappschalter verändert nur die Darstellung der RP-Leiste. Er ersetzt weder die gespeicherte Sichtbarkeit noch die Profil- oder Altersfreigabe. Klappe die Leiste wieder auf, wenn du die zugeordneten Aktionen und sichtbaren Eindrücke nutzen möchtest. Glance-Inhalte gehören zum Profil, nicht zu den abschaltbaren Hilfetexten."),
            [HelpTopicId.TargetContext] = new("Eigenes Profil und Spielziel", "Die RP-Leiste bleibt bei deinem eigenen Charakter; Zielprofile haben eine eigene Ansicht.", "Eine fremde Profilanzeige setzt eine bekannte, bestätigte und aktuell erlaubte Zuordnung voraus. Für unbekannte oder gesperrte Ziele werden keine Profilinhalte angenommen und keine automatischen Verbindungen aufgebaut. Eigene Statusschalter beziehen sich immer auf dein eigenes aktives Profil. Zielwechsel dürfen keine veralteten Inhalte des vorherigen Ziels stehen lassen."),
            [HelpTopicId.ExistingAdditionalContent] = new("Vorhandene Zusatzinhalte prüfen", "Ältere Profile können weitere öffentliche Angaben enthalten, die die vereinfachte Neuanlage nicht anbietet.", "Dazu gehören bereits gespeicherte Persönlichkeitsmerkmale, RP-Anknüpfungspunkte, Begleiter, Zusatzfelder oder weitergehende Absprachen. Die drei Profilbereiche löschen diese Daten nicht und machen sie nicht privat. Prüfe vorhandene Inhalte bewusst vor einem Export oder einer Freigabe des vollständigen Profils. Auch für ältere Inhalte gilt die gemeinsame Alterskennzeichnung."),
        });

    public static HelpTopic Get(HelpTopicId topic) => All[topic];
}
